-- Runtime schema parity for MySQL raw-SQL tables and post-baseline columns.
-- These objects are referenced by repositories/services but are not generated by Ent.

-- ============================================================
-- audit / reconciliation helper tables
-- ============================================================
CREATE TABLE IF NOT EXISTS `orphan_allowed_groups_audit` (
    `id` bigint NOT NULL AUTO_INCREMENT,
    `user_id` bigint NOT NULL,
    `group_id` bigint NOT NULL,
    `recorded_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (`id`),
    UNIQUE INDEX `orphan_allowed_groups_audit_user_group_key` (`user_id`, `group_id`),
    INDEX `idx_orphan_allowed_groups_audit_user_id` (`user_id`)
) CHARSET utf8mb4 COLLATE utf8mb4_bin;

CREATE TABLE IF NOT EXISTS `billing_usage_entries` (
    `id` bigint NOT NULL AUTO_INCREMENT,
    `usage_log_id` bigint NOT NULL,
    `user_id` bigint NOT NULL,
    `api_key_id` bigint NOT NULL,
    `subscription_id` bigint NULL,
    `billing_type` smallint NOT NULL,
    `applied` bool NOT NULL DEFAULT true,
    `delta_usd` decimal(20,10) NOT NULL DEFAULT 0,
    `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (`id`),
    UNIQUE INDEX `billing_usage_entries_usage_log_id_unique` (`usage_log_id`),
    INDEX `idx_billing_usage_entries_user_time` (`user_id`, `created_at`),
    INDEX `idx_billing_usage_entries_created_at` (`created_at`),
    CONSTRAINT `billing_usage_entries_usage_logs_usage_log` FOREIGN KEY (`usage_log_id`) REFERENCES `usage_logs` (`id`) ON DELETE CASCADE,
    CONSTRAINT `billing_usage_entries_users_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
    CONSTRAINT `billing_usage_entries_api_keys_api_key` FOREIGN KEY (`api_key_id`) REFERENCES `api_keys` (`id`) ON DELETE CASCADE,
    CONSTRAINT `billing_usage_entries_user_subscriptions_subscription` FOREIGN KEY (`subscription_id`) REFERENCES `user_subscriptions` (`id`) ON DELETE SET NULL
) CHARSET utf8mb4 COLLATE utf8mb4_bin;

CREATE TABLE IF NOT EXISTS `usage_billing_dedup` (
    `id` bigint NOT NULL AUTO_INCREMENT,
    `request_id` varchar(255) NOT NULL,
    `api_key_id` bigint NOT NULL,
    `request_fingerprint` varchar(64) NOT NULL,
    `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (`id`),
    UNIQUE INDEX `idx_usage_billing_dedup_request_api_key` (`request_id`, `api_key_id`),
    INDEX `idx_usage_billing_dedup_created_at_brin` (`created_at`)
) CHARSET utf8mb4 COLLATE utf8mb4_bin;

CREATE TABLE IF NOT EXISTS `usage_billing_dedup_archive` (
    `request_id` varchar(255) NOT NULL,
    `api_key_id` bigint NOT NULL,
    `request_fingerprint` varchar(64) NOT NULL,
    `created_at` datetime(6) NOT NULL,
    `archived_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (`request_id`, `api_key_id`)
) CHARSET utf8mb4 COLLATE utf8mb4_bin;

