CREATE TABLE IF NOT EXISTS `auth_identity_migration_reports` (
    `id` bigint NOT NULL AUTO_INCREMENT,
    `report_type` varchar(80) NOT NULL,
    `report_key` varchar(255) NOT NULL,
    `details` json NOT NULL,
    `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `resolved_at` datetime(6) NULL,
    `resolved_by_user_id` bigint NULL,
    `resolution_note` longtext NULL,
    PRIMARY KEY (`id`),
    INDEX `auth_identity_migration_reports_type_idx` (`report_type`),
    UNIQUE INDEX `auth_identity_migration_reports_type_key` (`report_type`, `report_key`),
    INDEX `idx_auth_identity_migration_reports_resolved_at` (`resolved_at`)
) CHARSET utf8mb4 COLLATE utf8mb4_bin;

