    CONSTRAINT `user_group_rate_multipliers_groups_group` FOREIGN KEY (`group_id`) REFERENCES `groups` (`id`) ON DELETE CASCADE
) CHARSET utf8mb4 COLLATE utf8mb4_bin;

CREATE TABLE IF NOT EXISTS `user_affiliates` (
    `user_id` bigint NOT NULL,
