    `aff_count` int NOT NULL DEFAULT 0,
    `aff_quota` decimal(20,8) NOT NULL DEFAULT 0,
    `aff_history_quota` decimal(20,8) NOT NULL DEFAULT 0,
    `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    PRIMARY KEY (`user_id`),
    UNIQUE INDEX `user_affiliates_aff_code_key` (`aff_code`),
    INDEX `idx_user_affiliates_inviter_id` (`inviter_id`),
    INDEX `idx_user_affiliates_aff_quota` (`aff_quota`),
    CONSTRAINT `user_affiliates_users_affiliate` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
    CONSTRAINT `user_affiliates_users_inviter` FOREIGN KEY (`inviter_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) CHARSET utf8mb4 COLLATE utf8mb4_bin;

CREATE TABLE IF NOT EXISTS `user_affiliate_ledger` (
    `id` bigint NOT NULL AUTO_INCREMENT,
