) CHARSET utf8mb4 COLLATE utf8mb4_bin;

-- ============================================================
-- payment audit idempotency hardening
-- ============================================================
DELETE p1
FROM `payment_audit_logs` p1
INNER JOIN `payment_audit_logs` p2
    ON p1.`order_id` = p2.`order_id`
   AND p1.`action` = p2.`action`
   AND p1.`id` > p2.`id`;

SET @idx_exists = (
    SELECT COUNT(1)
    FROM information_schema.statistics
    WHERE table_schema = DATABASE()
      AND table_name = 'payment_audit_logs'
      AND index_name = 'idx_payment_audit_logs_order_action_uniq'
);
SET @sql = IF(@idx_exists = 0, 'CREATE UNIQUE INDEX idx_payment_audit_logs_order_action_uniq ON payment_audit_logs (order_id, action)', 'SELECT 1');
PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;
